                      </Link>
                    )}
                  </li>
                ))}
              </ul>
            ) : <p className="subtle">No linked frames.</p>}
          </section>
        </div>
      )}
      {showHistory && (
        <HistoryDialog
          frameId={frameId}
          onClose={() => setShowHistory(false)}
          onJob={showImports}
        />
      )}
    </>
