      const { operationName, variables } = route.request().postDataJSON();
      operations.push({ operationName, variables });
      const attributes = {
        status: 'LIVE', statusReason: null, locationId: null, environment: 'Outdoor',
        siteNo: '214', address: 'Westminster', inventorySiteNo: 'INV-214', panelNumber: null,
        station: null, airport: null, latitude: null, longitude: null,
        distanceToClosestSchool: null, location: null, format: null, sizeCode: null,
        aspectRatioCode: null, tSize: null, pixelHeight: null, pixelWidth: null,
        illuminationTypeId: null, numberOfSlots: 0, impactWeight: '2.40000000000000001', premium: true,
        productionRateCard: null, productionRateCardLegacy: null, pricingGrade: null,
      };
      const frame = { frameId, attributes, versionId: String(version), current: true };
      const job = {
        jobId, status: puts > 1 ? 'COMPLETED' : 'AWAITING_UPLOAD', forceOverwrite: true,
        uploadExpiresAt: '2099-01-01T00:00:00Z', finishedAt: null,
        rowsRead: 0, rowsApplied: 0, rowsUnchanged: 0, rowsRejected: 0, failureCode: null,
      };
      switch (operationName) {
        case 'Frames':
          return route.fulfill({ json: { data: { frames: { page: 0, size: 25, hasNext: false, items: [frame] } } } });
        case 'FrameForEdit':
          versionReads += 1;
          return route.fulfill({ json: { data: { frame } } });
        case 'CreateFrame':
          return route.fulfill({ json: { data: { createFrame: { frameId: variables.frameId } } } });
        case 'UpdateFrame':
          updates += 1;
          if (updates === 1) {
            version = 2;
            return route.fulfill({ json: { errors: [{ message: 'Version changed', extensions: { code: 'CONFLICT' } }] } });
          }
          return route.fulfill({ json: { data: { updateFrame: { frameId } } } });
        case 'CreateImport':
          return route.fulfill({ json: { data: { createImportJob: {
            job, uploadUrl: origin + '/mock-upload', uploadHeaders: [{ name: 'Content-Type', value: 'text/csv' }],
          } } } });
        case 'ImportStatus':
          return route.fulfill({ json: { data: { importJob: job } } });
        default:
          throw new Error('Unexpected operation: ' + operationName);
      }
    });
    await page.route('**/mock-upload', async route => {
      puts += 1;
      assert.equal(route.request().method(), 'PUT');
      assert.equal(route.request().postData(), 'id\\nA\\n');
      await route.fulfill({ status: puts === 1 ? 500 : 200 });
    });

    const operation = name => page.waitForRequest(request =>
      request.url().endsWith('/api/graphql') && request.postDataJSON().operationName === name);
    const waitForQuery = async (name, act) => {
      const [request] = await Promise.all([operation(name), act()]);
      return request.postDataJSON().variables;
    };
    const expectValue = async (field, value) => {
      await field.evaluate((node, expected) => new Promise((resolve, reject) => {
        const start = performance.now();
        function check() {
          if (node.value === expected) return resolve();
          if (performance.now() - start > 3000) return reject(new Error('Expected ' + expected + ', got ' + node.value));
          requestAnimationFrame(check);
        }
        check();
      }), value);
    };
    await page.goto(origin);
    const row = page.getByRole('link', { name: frameId });
    await row.waitFor();
    await page.getByRole('searchbox').fill('  Westminster  ');
    let variables = await waitForQuery('Frames', () => page.getByRole('button', { name: 'Search', exact: true }).click());
    assert.deepEqual(variables, { page: 0, search: 'Westminster' });
    variables = await waitForQuery('Frames', () => page.getByLabel('Status', { exact: true }).selectOption('LIVE'));
    assert.deepEqual(variables, { page: 0, search: 'Westminster', statuses: ['LIVE'] });
    variables = await waitForQuery('Frames', () => page.getByRole('button', { name: 'Clear filters' }).click());
    assert.deepEqual(variables, { page: 0 });
    assert.equal(await page.getByRole('searchbox').inputValue(), '');
    assert.equal(await page.getByLabel('Status', { exact: true }).inputValue(), '');

    await page.getByRole('button', { name: 'Add a frame' }).click();
    let dialog = page.getByRole('dialog');
    await dialog.getByLabel('Frame ID (required)').fill(' NEW-01 ');
    await dialog.getByLabel('Status (required)').selectOption('DRAFT');
    await dialog.getByLabel('Town').fill('London');
    const create = dialog.getByRole('button', { name: 'Create frame' });
    await create.click();
    await dialog.getByRole('alert').getByText('Enter a two-letter country code', { exact: false }).waitFor();
    assert.equal(operations.filter(op => op.operationName === 'CreateFrame').length, 0);
    await dialog.getByLabel('Town').clear();
    await dialog.getByLabel('Number of slots').fill('0');
    await dialog.getByLabel('Impact weight').fill('1.24000000000000001');
    await dialog.getByLabel('Premium').check();
    variables = await waitForQuery('CreateFrame', () => create.click());
    assert.deepEqual(variables, {
      frameId: 'NEW-01',
      attributes: { status: 'DRAFT', numberOfSlots: 0, impactWeight: '1.24000000000000001', premium: true },
    });
    await dialog.waitFor({ state: 'hidden' });

    await page.getByRole('button', { name: 'Edit frame ' + frameId }).click();
    dialog = page.getByRole('dialog');
    await expectValue(dialog.getByLabel('Frame ID'), frameId);
    await expectValue(dialog.getByLabel('Number of slots'), '0');
    await expectValue(dialog.getByLabel('Impact weight'), '2.40000000000000001');
    assert.ok(await dialog.getByLabel('Premium').isChecked());
    const address = dialog.getByLabel('Address');
    await address.fill('Unsaved address');
    const save = dialog.getByRole('button', { name: 'Save changes' });
    variables = await waitForQuery('UpdateFrame', () => save.click());
    assert.equal(variables.expectedVersionId, '1');
    assert.equal(variables.attributes.address, 'Unsaved address');
    const reload = dialog.getByRole('button', { name: 'Reload latest version' });
    await reload.click();
    await expectValue(address, 'Westminster');
    assert.equal(versionReads, 2);
    await dialog.getByLabel('Premium').uncheck();
    variables = await waitForQuery('UpdateFrame', () => save.click());
    assert.equal(variables.expectedVersionId, '2');
    assert.equal(variables.attributes.inventorySiteNo, 'INV-214');
    assert.equal(variables.attributes.premium, false);
    await dialog.waitFor({ state: 'hidden' });

    await page.getByRole('button', { name: 'Imports', exact: true }).click();
    const token = page.getByLabel('Local operator token');
    const upload = page.getByRole('button', { name: 'Upload CSV' });
    await upload.click();
    await page.getByText('Enter a valid local operator token.').waitFor();
    await token.fill('a'.repeat(64));
    await upload.click();
    await page.getByText('Choose a non-empty CSV file up to 10 MiB.').waitFor();
    await page.getByLabel('Inventory CSV').setInputFiles({ name: 'inventory.csv', mimeType: 'text/csv', buffer: Buffer.from('id\\nA\\n') });
    const force = page.getByRole('checkbox', { name: 'Force overwrite' });
    const confirmed = page.getByRole('checkbox', { name: /I understand/ });
    await force.check();
    await confirmed.check();
    await force.uncheck();
    await force.check();
    assert.equal(await confirmed.isChecked(), false);
    await upload.click();
    await page.getByText('Confirm the forced overwrite before uploading.').waitFor();
    await confirmed.check();
    assert.deepEqual(await waitForQuery('CreateImport', () => upload.click()), { force: true });
    await page.getByText('Upload failed (HTTP 500).').waitFor();
    assert.equal(await force.isChecked(), false);
    await page.getByRole('button', { name: 'Retry upload' }).click();
    await page.getByText('Completed', { exact: true }).waitFor();
    assert.equal(puts, 2);
    assert.equal(operations.filter(op => op.operationName === 'CreateImport').length, 1);

    const lookup = page.getByLabel('Job ID');
    await lookup.fill('invalid');
    const open = page.getByRole('button', { name: 'Open', exact: true });
    await open.click();
    await page.getByText('Enter a valid import job ID.').waitFor();
    await lookup.fill('  ' + jobId.toUpperCase() + '  ');
    assert.deepEqual(await waitForQuery('ImportStatus', () => open.click()), { id: jobId });
    assert.equal(await token.inputValue(), 'a'.repeat(64));
    assert.deepEqual(errors, []);
    console.log('Search and reset, frame create validation and payload, version conflict reload, CSV validation and retry, and job lookup passed.');
  } finally {
    await browser.close();
  }
}

run().catch(error => {
  console.error(error);
  process.exitCode = 1;
}).finally(() => server.kill());
